#!/usr/bin/env bash
# Rewrite the download section of README.md for a release.
#
# Usage: update-readme.sh <tag> [owner/repo] [readme]
#
# Replaces everything between the `<!-- release:start -->` and
# `<!-- release:end -->` markers with the release version and direct
# download links for every target.
set -euo pipefail

tag=${1:?usage: update-readme.sh <tag> [owner/repo] [readme]}
repo=${2:-${GITHUB_REPOSITORY:-darioanguilla/fishies-rs}}
readme=${3:-README.md}
base="https://github.com/$repo/releases/download/$tag"

grep -q '<!-- release:start -->' "$readme" && grep -q '<!-- release:end -->' "$readme" \
  || { echo "release markers not found in $readme" >&2; exit 1; }

# links for one target: bare executable + archive
cell() {
  local target=$1 name="fishies-$tag-$1"
  if [[ "$target" == *windows* ]]; then
    echo "[\`.exe\`]($base/$name.exe) · [\`.zip\`]($base/$name.zip)"
  else
    echo "[executable]($base/$name) · [\`.tar.gz\`]($base/$name.tar.gz)"
  fi
}

section=$(cat <<EOF
<!-- release:start -->
<!-- This section is generated by the Release workflow (.github/scripts/update-readme.sh). -->
Latest release: **$tag** ([release notes](https://github.com/$repo/releases/tag/$tag), [\`SHA256SUMS.txt\`]($base/SHA256SUMS.txt))

| OS      | x86_64 | arm64 | RISC-V |
|---------|--------|-------|--------|
| Linux   | $(cell x86_64-unknown-linux-gnu) | $(cell aarch64-unknown-linux-gnu) | $(cell riscv64gc-unknown-linux-gnu) |
| Windows | $(cell x86_64-pc-windows-msvc) | $(cell aarch64-pc-windows-msvc) | n/a |
| macOS   | $(cell x86_64-apple-darwin) | $(cell aarch64-apple-darwin) | n/a |
<!-- release:end -->
EOF
)

tmp=$(mktemp)
SECTION="$section" awk '
  /<!-- release:start -->/ { print ENVIRON["SECTION"]; skip = 1; next }
  /<!-- release:end -->/   { skip = 0; next }
  !skip
' "$readme" > "$tmp"
# keep the README's line endings and permissions: overwrite in place
cat "$tmp" > "$readme"
rm -f "$tmp"
